mapper.select:
select QUOTE_DATE quoteDate, QUOTE_ID quoteId, CL_ORD_ID clOrdId from QUOTE_ID_CONVER where 1=1
AND QUOTE_DATE = to_date(#{quoteDate},'yyyy-MM-dd')
AND QUOTE_ID = #{quoteId}
AND CL_ORD_ID = #{clOrdId}

mapper.insert:
insert into QUOTE_ID_CONVER (QUOTE_DATE, QUOTE_ID, CL_ORD_ID, CREATE_USER,
    CREATE_TIME, UPDATE_USER, UPDATE_TIME
    )
values (#{quoteDate,jdbcType=DATE}, #{quoteId,jdbcType=VARCHAR}, #{clOrdId,jdbcType=VARCHAR},
    #{createUser,jdbcType=VARCHAR},  #{createTime,jdbcType=TIMESTAMP},
    #{updateUser,jdbcType=VARCHAR}, #{updateTime,jdbcType=TIMESTAMP}
    )
